fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper: prefix sum S(k)
    fn prefix_sum(k: i16) -> i16 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // Convert to i16 to avoid overflow in intermediate calculations
            let l = l as i16;
            let r = r as i16;

            let sum = prefix_sum(r) - prefix_sum(l - 1);
            sum as i8
        })
        .collect()
}